def chunk_into_n_parts(lst, n):
    if n <= 0:
        return []
    if n >= len(lst):
        return [lst[i:i+1] for i in range(len(lst))]
    parts = []
    base = len(lst) // n
    remainder = len(lst) % n
    for i in range(n):
        start = i * base + min(i, remainder)
        end = (i + 1) * base + (i < remainder)
        parts.append(lst[start:end])
    return parts
```

