def add_weeks_to_date(y, m, d, n_weeks):
    day = d + 7 * n_weeks
    month = m
    year = y
    while day < 1:
        prev_month = month - 1
        if prev_month == 0:
            prev_month = 12
            prev_year = year - 1
        else:
            prev_year = year
        if prev_month in (1, 3, 5, 7, 8, 10, 12):
            days_in_month = 31
        elif prev_month in (4, 6, 9, 11):
            days_in_month = 30
        elif prev_month == 2:
            if prev_year % 4 == 0 and (prev_year % 100 != 0 or prev_year % 400 == 0):
                days_in_month = 29
            else:
                days_in_month = 28
        day += days_in_month
        month = prev_month
        if month == 12:
            year = prev_year
    while day > (31 if m in (1, 3, 5, 7, 8, 10, 12) else 30 if m in (4, 6, 9, 11) else 28 + (m == 2 and y % 4 == 0 and (y % 100 != 0 or y % 400 == 0))):
        day -= 1
        if day == 0:
            next_month = month + 1
            if next_month > 12:
                next_month = 1
                next_year = year + 1
            else:
                next_year = year
            month = next_month
            year = next_year
    return (year, month, day)
