def format_currency(amount):
    if amount < 0:
        sign = '-'
    else:
        sign = ''
    cents = int(round(amount * 100))
    if cents < 0:
        cents = -cents
    dollars, cents = divmod(cents, 100)
    dollars = int(dollars)
    dollars, cents = divmod(dollars, 1000)
    parts = []
    while dollars:
        parts.append(dollars % 1000)
        dollars //= 1000
    comma_separated = ''
    for part in reversed(parts):
        if part:
            comma_separated += f'{part:,}'
    result = f'{sign}$'
    if comma_separated:
        result += comma_separated
    result += f'.{cents:02d}'
    return result
