def caesar_shift(s, shift):
    # The Wren implementation wraps shift with % 26, so we do the same.
    shift %= 26
    result = []
    for c in s:
        if 'a' <= c <= 'z':
            base = ord('a')
        elif 'A' <= c <= 'Z':
            base = ord('A')
        else:
            result.append(c)
            continue
        i = ord(c) - base
        i = (i + shift) % 26
        result.append(chr(base + i))
    return ''.join(result)
