def convert_base_to_base(s, from_base, to_base):
    if from_base < 2 or to_base < 2:
        return ''
    if s == '0':
        return '0'
    num = 0
    for c in s:
        if c.isdigit():
            d = int(c)
        else:
            d = ord(c) - ord('a') + 10
        num = num * from_base + d
    if num == 0:
        return '0'
    result = []
    while num:
        num, r = divmod(num, to_base)
        if r < 10:
            result.append(str(r))
        else:
            result.append(chr(r - 10 + ord('a')))
    return ''.join(reversed(result))
