def reorder_by_priority_groups(items, category_of, priority):
    # Separate items by category.
    groups = {}
    for name in items:
        cat = category_of[name]
        if cat not in groups:
            groups[cat] = []
        groups[cat].append(name)

    # Apply priority order to the categories.
    order = []
    for cat in priority:
        if cat in groups:
            order.append(groups[cat])
    # Order is the list of lists of items in priority order.

    # Now, compute the out of order items.
    order.append([])  # Makes life easier for the next loop.
    for name in items:
        if not name in order[0]:  # name is not yet placed.
            order[-1].append(name)

    # Flatten the lists.
    result = []
    for lst in order:
        result.extend(lst)
    return result
