```python
def dedent_lines(text, n):
    # Remove the newline from the end, if any
    lines = text.split('\n')
    result = []
    for line in lines:
        if line:
            stripped = line.lstrip(' ')
            m = len(line) - len(stripped)
            if m > 0:
                # prevent over-collapsing
                m = min(m, n)
                result.append(line[m:])
            else:
                result.append(line)
    return '\n'.join(result)
```

